require dirname(__DIR__).'/includes/bootstrap.php';require_staff_or_admin();$rows=fetch_all('SELECT d.*,t.t_name,s.s_name FROM tbl_devices d JOIN tbl_devices_type t ON t.t_id=d.ref_t_id JOIN tbl_devices_status s ON s.s_id=d.ref_s_id WHERE d.ref_s_id=3 ORDER BY d.no DESC');render_header('ครุภัณฑ์ชำรุด','damaged');?>
<div class="page-intro"><div><h2>ครุภัณฑ์ชำรุด</h2><p>รายการที่ถูกระบุว่าชำรุดจากการรับคืนหรือการแก้ไขข้อมูลครุภัณฑ์</p></div><a class="btn btn-soft" href="<?=e(url('staff/devices.php'))?>">ครุภัณฑ์ทั้งหมด</a></div><div class="card"><div class="table-tools"><div class="table-search"><input type="search" placeholder="ค้นหาครุภัณฑ์ชำรุด…" data-table-search="#damagedTable"></div><span class="table-meta"><?=count($rows)?> รายการ</span></div><div class="table-wrap"><table class="data-table" id="damagedTable"><thead><tr><th>ครุภัณฑ์</th><th>ประเภท</th><th>รายละเอียด</th><th>หมายเหตุ</th><th>จัดการ</th></tr></thead><tbody><?php if(!$rows):?><tr data-empty><td colspan="5"><div class="empty-state"><div class="empty-icon">✓</div><h3>ไม่มีครุภัณฑ์ชำรุด</h3></div></td></tr><?php else:foreach($rows as $r):$img=device_image($r);?><tr><td><div class="device-cell"><?php if($img):?><img class="device-thumb" src="<?=e($img)?>" alt=""><?php else:?><span class="device-placeholder">ET</span><?php endif;?><span><b class="cell-title"><?=e($r['d_name'])?></b><small class="cell-sub"><?=e($r['d_id'])?></small></span></div></td><td><?=e($r['t_name'])?></td><td><?=e($r['d_detail']?:'-')?></td><td><?=e($r['d_remark']?:'-')?></td><td><a class="btn btn-soft btn-sm" href="<?=e(url('staff/device_form.php?no='.(int)$r['no']))?>">แก้ไขสถานะ</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php render_footer();?>
